'use strict';
const $=id=>document.getElementById(id), canvas=$('world'),ctx=canvas.getContext('2d'), mini=$('minimap'),mc=mini.getContext('2d');
const SIZE=2400,CELL=40,N=SIZE/CELL;
const buildings={wall:{name:"Wall",gold:15,wood:35,hp:700,size:16},tower:{name:'Watchtower',gold:140,wood:160,hp:1000,size:24,damage:22,range:290,reload:1.1},bastion:{name:'Siege Bastion',gold:280,wood:240,hp:1600,size:32,damage:60,range:340,reload:2.6,splash:60},base:{name:'Stronghold',gold:400,wood:300,hp:2200,size:45},barracks:{name:'Infantry Lodge',gold:160,wood:120,hp:900,size:32},forge:{name:'Siege Works',gold:200,wood:180,hp:850,size:32},roost:{name:'Sky Roost',gold:220,wood:200,hp:750,size:32},altar:{name:'Hero Sanctum',gold:240,wood:180,hp:950,size:34},mill:{name:'Harvest Guild',gold:140,wood:100,hp:650,size:28},armory:{name:'Infantry Armory',gold:180,wood:140,hp:700,size:28},foundry:{name:'Artillery Foundry',gold:200,wood:160,hp:700,size:28}};
const units={worker:{gold:50,wood:0,hp:75,damage:4,range:22,speed:85,time:10},melee:{gold:70,wood:25,hp:180,damage:18,range:25,speed:80,time:6},ranged:{gold:90,wood:40,hp:105,damage:15,range:160,speed:80,time:7},sniper:{gold:140,wood:60,hp:65,damage:38,range:215,speed:70,time:9},siege:{gold:180,wood:110,hp:210,damage:65,range:260,speed:45,time:12},air:{gold:170,wood:100,hp:150,damage:23,range:140,speed:130,time:11},hero:{gold:250,wood:150,hp:500,damage:32,range:100,speed:85,time:15}};
const names={human:{worker:'Peasant',melee:'Dawn Knight',ranged:'Longbow Ranger',sniper:'Royal Marksman',siege:'Bombard',air:'Gryphon Rider',hero:'Sun Marshal'},horde:{worker:'Peon',melee:'Orc Ravager',ranged:'Troll Spearthrower',sniper:'Shadow Hunter',siege:'Rock Hewer',air:'Wyvern Rider',hero:'Stormcaller'}};
let faction='human',state=null,cam={x:0,y:0},keys={},selected=[],placement=null,commandMode=null,orderMarker=null,drag=null,mouse={x:0,y:0},last=0,paused=false,toastTimer=0,uid=0;
function toast(s){$('toast').textContent=s;$('toast').style.display='block';toastTimer=3;}
function entity(type,owner,x,y,building=false){const def=(building?buildings:units)[type];const e={id:++uid,type,owner,x,y,hp:def.hp,max:def.hp,building,size:building?def.size:type==='siege'?14:type==='hero'?13:9,level:1,cool:0,queue:[],order:null,facing:0,walkUntil:0,action:null,rally:null};state.entities.push(e);return e;}
function start(){const colors=[$('color').value,$('c1').value,$('c2').value];const count=$('ai2').value==='off'?2:3;if(new Set(colors.slice(0,count)).size!==count){toast('Choose different banner colors.');alert('Each player needs a different banner color.');return;}state={map:mapChoice,mountains:makeMountains(mapChoice),wallVersion:0,blockCache:{},effects:[],entities:[],resources:[],players:[],seen:new Uint8Array(N*N),visible:new Uint8Array(N*N),time:0,count:3.6,ended:false,ai:0};selected=[];placement=null;commandMode=null;orderMarker=null;terrainLayer=null;paused=false;cam={x:0,y:0};$('pause').textContent='Ⅱ Pause';$('end').hidden=true;
const spots=spawnLocations();state.spawns=spots;for(let i=0;i<count;i++){state.players.push({faction:i===0?faction:$(i===1?'ai1':'ai2').value,color:colors[i],gold:100,wood:100,gather:0,infantry:0,artillery:0,fire:0,capacity:0});const [x,y]=spots[i];entity('base',i,x,y,true);for(let w=0;w<4;w++)entity('worker',i,x-60+w*30,y+85);}
let seed=83;function rnd(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
for(let i=0;i<190;i++){const x=80+rnd()*2240,y=80+rnd()*2240;if(spots.some(p=>Math.hypot(p[0]-x,p[1]-y)<140))continue;state.resources.push({x,y,type:i%5===0?'gold':'wood',amount:i%5===0?4500:1000});}for(const [x,y] of spots){for(let n=0;n<9;n++)state.resources.push({x:x+160+n%3*35,y:y+80+Math.floor(n/3)*35,type:'wood',amount:1200});state.resources.push({x:x-110,y:y-100,type:'gold',amount:6000});}
state.resources=state.resources.filter(r=>!(state.mountains||[]).some(m=>Math.abs(m.x-r.x)<m.half+18&&Math.abs(m.y-r.y)<m.half+18));$('menu').hidden=true;$('mapMenu').hidden=true;$('game').hidden=false;resize();cam.x=spots[0][0]-canvas.width/2;cam.y=spots[0][1]-canvas.height/2;clampCam();fog();updateUI();}
function setFaction(next){faction=next;document.querySelectorAll('.faction').forEach(e=>e.classList.toggle('selected',e.dataset.faction===next));$('selectedRaceBanner').dataset.faction=next;$('raceBannerName').textContent=next==='human'?'The Dawnward':'The Dominion';$('raceBannerType').textContent=next==='human'?'Human kingdoms':'Orc & troll dominion';}
document.querySelectorAll('.faction').forEach(el=>el.onclick=()=>setFaction(el.dataset.faction));$('start').onclick=start;$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'▶ Resume':'Ⅱ Pause';};$('exit').onclick=()=>{state=null;$('game').hidden=true;$('menu').hidden=false;};
function resize(){canvas.width=canvas.clientWidth;canvas.height=canvas.clientHeight;}window.addEventListener('resize',resize);
function visible(x,y){return state.visible[Math.floor(y/CELL)*N+Math.floor(x/CELL)]===1;}
function fog(){state.visible.fill(0);for(const e of state.entities.filter(e=>e.owner===0&&e.hp>0)){const r=e.building?260:e.type==='air'?320:230;for(let y=Math.max(0,Math.floor((e.y-r)/CELL));y<Math.min(N,Math.ceil((e.y+r)/CELL));y++)for(let x=Math.max(0,Math.floor((e.x-r)/CELL));x<Math.min(N,Math.ceil((e.x+r)/CELL));x++)if(Math.hypot(x*CELL+20-e.x,y*CELL+20-e.y)<r){state.visible[y*N+x]=1;state.seen[y*N+x]=1;}}}
function pay(owner,g,w){const p=state.players[owner];if(p.gold<g||p.wood<w){if(owner===0)toast('Not enough gold or lumber.');return false;}p.gold-=g;p.wood-=w;return true;}
function train(b,type){const d=units[type];if(type==='worker'&&workerCount(b.owner)>=workerLimit(b.owner)){if(b.owner===0)toast('Collector limit reached: '+workerLimit(b.owner)+'.');return;}if(b.construction){if(b.owner===0)toast('Finish construction before training troops.');return;}if(b.queue.length>=5){if(b.owner===0)toast('Production queue full.');return;}if(type==='hero'&&state.entities.some(e=>e.owner===b.owner&&(e.type==='hero'||e.queue.some(q=>q.type==='hero')))){if(b.owner===0)toast('Only one hero per faction.');return;}if(pay(b.owner,d.gold,d.wood))b.queue.push({id:++uid,type,left:d.time,total:d.time,gold:d.gold,wood:d.wood});updateUI();}
function upgrade(b,key){const p=state.players[b.owner],level=key==='stronghold'?(b.level||1):p[key]||0;if(key==='fire'&&(p.faction!=='human'||b.type!=='armory')||key==='stronghold'&&b.type!=='base'||key==='capacity'&&b.type!=='mill')return;if(b.construction||b.research||state.entities.some(e=>e.owner===b.owner&&e.research?.key===key)){if(b.owner===0)toast('Construction or this upgrade is already in progress.');return;}if(level>=(key==='fire'?1:key==='stronghold'?4:3))return;const required=['fire','stronghold'].includes(key)?1:level+1;if(strongholdLevel(b.owner)<required){if(b.owner===0)toast('Requires Stronghold level '+required+'.');return;}const cost=researchPrice(key,level);if(pay(b.owner,cost.gold,cost.wood)){b.research={key,level:level+1,total:cost.time,left:cost.time,gold:cost.gold,wood:cost.wood};updateUI();}}

function build(type,x,y,owner=0,append=false){const d=buildings[type],workers=state.entities.filter(e=>e.owner===owner&&e.type==='worker'&&e.hp>0&&(owner!==0||selected.includes(e)));if(!workers.length){if(owner===0)toast('Select a living collector to construct buildings.');return false;}if(x<d.size||y<d.size||x>SIZE-d.size||y>SIZE-d.size)return false;if((state.mountains||[]).some(m=>Math.abs(m.x-x)<m.half+d.size&&Math.abs(m.y-y)<m.half+d.size)){if(owner===0)toast('Cannot build in the mountains.');return false;}if(type==='wall'){x=Math.floor(x/32)*32+16;y=Math.floor(y/32)*32+16;}if(owner===0&&!visible(x,y)){toast('Build within explored, visible territory.');return false;}if(type==='wall'&&state.entities.some(e=>!e.building&&e.type!=='air'&&e.hp>0&&Math.abs(e.x-x)<16+e.size&&Math.abs(e.y-y)<16+e.size)){if(owner===0)toast('Move ground troops out of the wall construction area.');return false;}if(state.entities.some(e=>e.building&&Math.hypot(e.x-x,e.y-y)<(type==='wall'&&e.type==='wall'?31:e.size+d.size+25))||state.resources.some(e=>e.amount>0&&Math.hypot(e.x-x,e.y-y)<d.size+20)){if(owner===0)toast('Construction area is blocked.');return false;}if(pay(owner,d.gold,d.wood)){const b=entity(type,owner,x,y,true);b.construction={total:buildTimes[type],left:buildTimes[type],active:false};b.hp=b.max*.2;const worker=workers.sort((a,b)=>(a.tasks?.length||0)-(b.tasks?.length||0)||Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0];assignBuilder(worker,b,append||worker.order?.kind==='build');return true;}return false;}
function formatGameTime(seconds){const elapsed=Math.max(0,Math.floor(seconds));return String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(elapsed%60).padStart(2,'0');}
function updateUI(){
 if(!state)return;selected=selected.filter(e=>e.hp>0);const p=state.players[0],e=selected[0];
 $('gameTimer').textContent=formatGameTime(state.time);
 $('resources').innerHTML=`<span>◆ <b>${Math.floor(p.gold)}</b> gold</span><span>♣ <b>${Math.floor(p.wood)}</b> lumber</span><span>⚑ ${state.entities.filter(e=>e.owner===0&&!e.building).length} troops</span><span>♟ ${state.entities.filter(e=>e.owner===0&&e.type==='worker').length}/${workerLimit(0)} collectors</span>`;
 $('selectionTitle').textContent=e?(selected.length>1?selected.length+(selected.every(s=>s.building)?' buildings':' units'):e.building?buildings[e.type].name:names[p.faction][e.type]):'Your command awaits';
 $('selectionInfo').textContent=e?`${Math.ceil(e.hp)} / ${e.max} health${e.type==='base'?' · Stronghold level '+(e.level||1):''}${e.construction?' · Under construction':''}`:'Select units, choose Move, then left-click the destination.';
 const stats=e?(e.building?[...(buildings[e.type].damage?[['Damage',buildings[e.type].damage],['Range',buildings[e.type].range]]:[]),['Vision',260]]:characterStats(e)):[];
 $('selectionStats').innerHTML=stats.map(([name,value])=>`<div><span>${name}</span><b>${value}</b></div>`).join('');
 $('queue').textContent=e?.tasks?.length?e.tasks.length+' queued tasks: '+e.tasks.map(t=>t.kind).join(' → '):e?.research?'Researching '+(e.research.key==='stronghold'?'Stronghold level '+e.research.level:e.research.key)+' · '+Math.ceil(e.research.left)+'s':'';
 const a=$('actions');a.innerHTML='';
 function button(label,cost,fn,opts={}){const b=document.createElement('button');b.innerHTML=(opts.picture?buildingPicture(opts.picture,p.faction==='horde'):'')+`<span>${label}<small>${cost}</small></span>`;b.onclick=fn;b.disabled=!!opts.disabled;if(opts.picture)b.className='build-action';a.appendChild(b);}
 updateWorkQueue();if(!e||e.construction)return;
 if(e.building&&['base','barracks','forge','roost','altar'].includes(e.type)){button('Set rally point','Left-click destination',()=>{placement=null;commandMode='rally';toast('Left-click the rally destination.');});if(e.rally)button('Clear rally point','Spawn beside building',()=>{selected.filter(b=>b.building&&b.type===e.type).forEach(b=>b.rally=null);updateUI();});}
 if(!e.building){button('Move','Left-click destination · M',()=>{placement=null;commandMode='move';toast('Move selected units: left-click a destination.');});button('Attack / gather','Click enemy, site or resource',()=>{placement=null;commandMode='command';toast('Left-click a target to attack, gather or construct.');});button('Stop','Clear task sequence',()=>{commandMode=null;selected.forEach(s=>{s.order=null;s.jobs=[];s.tasks=[];});});button('Hold position','Attack enemies in range',()=>{commandMode=null;selected.forEach(s=>{s.order={kind:'hold'};s.jobs=[];s.tasks=[];});});}
 if(e.type==='worker')button('Repair Stronghold','20 health/s per worker · Left-click your Stronghold',()=>{placement=null;commandMode='repair';toast('Left-click a damaged friendly Stronghold to repair it.');});
 if(e.type==='worker')for(const [type,d] of Object.entries(buildings)){if(type==='base')continue;button(d.name,`${d.gold} gold · ${d.wood} lumber`,()=>{commandMode=null;placement=type;toast('Place '+d.name+' with a left click.');},{picture:type});}
 if(e.building){const options={base:['worker'],barracks:['melee','ranged','sniper'],forge:['siege'],roost:['air'],altar:['hero']}[e.type]||[];for(const t of options)button(names[p.faction][t],`${units[t].gold} gold · ${units[t].time}s`,()=>{const choices=selected.filter(b=>b.building&&b.type===e.type&&!b.construction&&b.queue.length<5).sort((a,b)=>a.queue.length-b.queue.length);if(choices[0])train(choices[0],t);},{disabled:t==='worker'&&workerCount(0)>=workerLimit(0)});
 function researchButton(key,label){const level=key==='stronghold'?(e.level||1):p[key]||0,max=key==='fire'?1:key==='stronghold'?4:3,price=researchPrice(key,level),required=['fire','stronghold'].includes(key)?1:level+1,locked=strongholdLevel(0)<required;button(level>=max?label+' · MAX':label+(key==='fire'?'':' '+(level+1)),level>=max?'Completed':locked?'Requires Stronghold level '+required:`${price.gold} gold · ${price.wood} lumber · ${price.time}s`,()=>upgrade(e,key),{disabled:level>=max||locked||!!e.research});}
 if(e.type==='base')researchButton('stronghold','Upgrade Stronghold');const key={mill:'gather',armory:'infantry',foundry:'artillery'}[e.type];if(key)researchButton(key,'Upgrade '+key);if(e.type==='mill')researchButton('capacity','Collector capacity');if(e.type==='armory'&&p.faction==='human')researchButton('fire','Fire arrows');
 }
}

function point(ev){const r=canvas.getBoundingClientRect();return{x:ev.clientX-r.left+cam.x,y:ev.clientY-r.top+cam.y};}
function issueCommand(p,append=false){
 const producers=selected.filter(e=>e.building&&['base','barracks','forge','roost','altar'].includes(e.type));
 if(producers.length&&(commandMode==='rally'||!selected.some(e=>!e.building))){const resource=state.resources.find(r=>r.amount>0&&visible(r.x,r.y)&&Math.hypot(r.x-p.x,r.y-p.y)<30);producers.forEach(e=>e.rally={x:Math.max(10,Math.min(SIZE-10,p.x)),y:Math.max(10,Math.min(SIZE-10,p.y)),resource:resource||null});orderMarker={x:p.x,y:p.y,left:1};commandMode=null;toast('Rally point set. New troops will go here.');updateUI();return;}
 const troops=selected.filter(e=>!e.building&&e.hp>0);
 if(!troops.length){toast('Select a unit first, then choose a destination.');return;}
 const repairTarget=commandMode!=='move'&&state.entities.find(e=>e.owner===0&&e.type==='base'&&e.hp>0&&!e.construction&&e.hp<e.max&&hitFriendly(e,p));
 if(commandMode==='repair'||repairTarget&&troops.some(e=>e.type==='worker')){if(!repairTarget){toast('Choose a damaged friendly Stronghold.');return;}troops.filter(e=>e.type==='worker').forEach(e=>queueTask(e,{kind:'repair',target:repairTarget},append));commandMode=null;placement=null;toast(append?'Repair added to task sequence.':'Peasants ordered to repair the Stronghold.');updateUI();return;}
 const forcedMove=commandMode==='move';const target=!forcedMove&&state.entities.find(e=>e.owner!==0&&visible(e.x,e.y)&&hitFriendly(e,p));
 const site=!forcedMove&&state.entities.find(e=>e.owner===0&&e.construction&&hitFriendly(e,p));
 const resource=!forcedMove&&state.resources.find(r=>r.amount>0&&visible(r.x,r.y)&&Math.hypot(r.x-p.x,r.y-p.y)<30);
 if(site&&troops.some(e=>e.type==='worker')){troops.filter(e=>e.type==='worker').forEach(e=>assignBuilder(e,site,append));toast('Builders assigned.');return;}
 troops.forEach((e,i)=>queueTask(e,target?{kind:'attack',target}:e.type==='worker'&&resource?{kind:'gather',target:resource}:{kind:'move',x:Math.max(10,Math.min(SIZE-10,p.x+(i%5)*32)),y:Math.max(10,Math.min(SIZE-10,p.y+Math.floor(i/5)*32))},append));
 orderMarker={x:p.x,y:p.y,left:1,kind:target?'attack':'move',target:target||null};commandMode=null;placement=null;
 toast(append?'Task added to sequence.':target?'Attack order issued.':resource&&troops.some(e=>e.type==='worker')?'Gather order issued.':'Move order issued.');
}
canvas.onpointerdown=ev=>{if(!state||state.count>0||state.ended)return;if(paused){toast('Resume the game to issue orders.');return;}const p=point(ev);mouse=p;if(ev.button===0){if(ev.shiftKey&&!placement&&!commandMode&&selected.some(e=>!e.building)&&!state.entities.some(e=>e.owner===0&&hitFriendly(e,p)&&!e.construction)){issueCommand(p,true);return;}if(!placement&&!commandMode&&selected.some(e=>!e.building)&&state.entities.some(e=>e.owner!==0&&e.hp>0&&visible(e.x,e.y)&&hitFriendly(e,p))){issueCommand(p,ev.shiftKey);return;}if(commandMode){issueCommand(p,ev.shiftKey);return;}if(placement){if(build(placement,p.x,p.y,0,ev.shiftKey)&&placement!=='wall')placement=null;updateUI();return;}drag={x:p.x,y:p.y,shift:ev.shiftKey};canvas.setPointerCapture?.(ev.pointerId);}if(ev.button===2){ev.preventDefault();if(commandMode==='move'){toast('Move mode: use a left click for the destination.');return;}issueCommand(p,ev.shiftKey);}};
canvas.onpointermove=ev=>{mouse=point(ev);const enemy=state&&state.entities.find(e=>e.owner!==0&&e.hp>0&&visible(e.x,e.y)&&hitFriendly(e,mouse));canvas.style.cursor=enemy&&selected.some(e=>!e.building)?'crosshair':'default';};canvas.onpointerup=ev=>{if(ev.button!==0||!drag)return;const p=point(ev),box=Math.hypot(p.x-drag.x,p.y-drag.y)>8;const picked=state.entities.filter(e=>e.owner===0&&(box?e.x>=Math.min(p.x,drag.x)&&e.x<=Math.max(p.x,drag.x)&&e.y>=Math.min(p.y,drag.y)&&e.y<=Math.max(p.y,drag.y)&&!e.building:hitFriendly(e,p)));selected=drag.shift?[...new Set([...selected,...picked])]:box?picked:picked.slice(-1);drag=null;updateUI();};function hitFriendly(e,p){return e.building?Math.hypot(e.x-p.x,e.y-p.y)<e.size+10:Math.abs(e.x-p.x)<=e.size+12&&p.y>=e.y-35&&p.y<=e.y+20;}
canvas.ondblclick=ev=>{if(!state||state.count>0||state.ended||placement||commandMode)return;const p=point(ev);const unit=state.entities.filter(e=>e.owner===0&&e.hp>0&&hitFriendly(e,p)).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!unit)return;const same=state.entities.filter(e=>e.owner===0&&e.building===unit.building&&e.hp>0&&e.type===unit.type&&e.x>=cam.x&&e.x<=cam.x+canvas.width&&e.y>=cam.y&&e.y<=cam.y+canvas.height);selected=ev.shiftKey?[...new Set([...selected,...same])]:same;drag=null;toast('Selected all '+same.length+' '+(unit.building?buildings[unit.type].name:names[state.players[0].faction][unit.type])+(unit.building?' buildings.':' units.'));updateUI();};
canvas.oncontextmenu=e=>e.preventDefault();window.onkeydown=e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key)&&state)e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='m'&&state&&selected.some(s=>!s.building)){placement=null;commandMode='move';toast('Left-click a destination to move.');}if(e.key==='Escape'){placement=null;commandMode=null;drag=null;}};window.onkeyup=e=>keys[e.key.toLowerCase()]=false;window.onblur=()=>{keys={};drag=null;};mini.onmousedown=ev=>{if(!state||state.count>0||state.ended)return;if(commandMode==='move'&&ev.button!==0){toast('Move mode: left-click the minimap destination.');return;}const r=mini.getBoundingClientRect(),p={x:(ev.clientX-r.left)/r.width*SIZE,y:(ev.clientY-r.top)/r.height*SIZE};if(!ev.altKey&&(ev.button===2||commandMode||selected.some(e=>!e.building))&&!paused){issueCommand(p,ev.shiftKey);return;}cam.x=p.x-canvas.width/2;cam.y=p.y-canvas.height/2;clampCam();};mini.oncontextmenu=ev=>ev.preventDefault();

function clampCam(){cam.x=Math.max(0,Math.min(SIZE-canvas.width,cam.x));cam.y=Math.max(0,Math.min(SIZE-canvas.height,cam.y));}
function move(e,x,y,dt){
 const distance=Math.hypot(x-e.x,y-e.y);if(distance<=3)return distance;
 let goal={x,y};
 if(e.type!=='air'&&!clearWallLine(e,x,y)){
  if(!e.route||e.route.version!==state.wallVersion||Math.hypot(e.route.x-x,e.route.y-y)>24||state.time-e.route.time>2){e.route={x,y,version:state.wallVersion,time:state.time,points:wallRoute(e,x,y)};}
  while(e.route.points.length&&Math.hypot(e.route.points[0].x-e.x,e.route.points[0].y-e.y)<5)e.route.points.shift();
  if(!e.route.points.length)return distance;goal=e.route.points[0];
 }else e.route=null;
 const d=Math.hypot(goal.x-e.x,goal.y-e.y),step=Math.min(units[e.type].speed*dt,d);if(d<=0)return distance;
 e.facing=Math.atan2(goal.y-e.y,goal.x-e.x);const nx=Math.max(10,Math.min(SIZE-10,e.x+(goal.x-e.x)/d*step)),ny=Math.max(10,Math.min(SIZE-10,e.y+(goal.y-e.y)/d*step));
 if(e.type==='air'||clearWallLine(e,nx,ny)){e.walkUntil=state.time+.12;e.x=nx;e.y=ny;}
 return distance;
}

