function treeAvailable(r,e){if(!r.collectorId||r.collectorId===e.id)return true;const other=state.entities.find(w=>w.id===r.collectorId&&w.hp>0);return !other||other.order?.kind!=='gather'||other.order.target!==r||Math.hypot(other.x-r.x,other.y-r.y)>30;}
function claimTree(e,o){const r=o.target;if(r.type!=='wood')return true;if(treeAvailable(r,e)){r.collectorId=e.id;return true;}const alternative=state.resources.filter(t=>t.type==='wood'&&t.amount>0&&t!==r&&treeAvailable(t,e)&&Math.hypot(t.x-r.x,t.y-r.y)<180).sort((a,b)=>Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y))[0];if(alternative){o.target=alternative;e.action=null;e.route=null;}return false;}
function makeMountains(key=mapChoice){const peaks=[];for(const [cx,cy,angle] of mapDefinitions[key].ridges)for(let i=-4;i<=4;i++){const x=cx+Math.cos(angle)*i*60,y=cy+Math.sin(angle)*i*60;peaks.push({x,y,half:30+(i%3+3)%3*4,height:65+(i%4+4)%4*12});}return peaks;}
function groundObstacles(){return [...state.entities.filter(w=>w.type==='wall'&&w.hp>0&&!w.construction).map(w=>({x:w.x,y:w.y,half:16})),...(state.mountains||[])];}
