let mapChoice='highlands';
function chooseMap(key){mapChoice=key;document.querySelectorAll('[data-map]').forEach(el=>el.classList.toggle('selected',el.dataset.map===key));$('mapName').textContent=mapDefinitions[key].name;}
function spawnLocations(random=Math.random){const spots=[[250,300],[2080,2000],[2070,300],[300,2050]];for(let i=spots.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[spots[i],spots[j]]=[spots[j],spots[i]];}return spots;}
function strongholdLevel(owner){return Math.max(1,...state.entities.filter(e=>e.owner===owner&&e.type==='base'&&e.hp>0&&!e.construction).map(e=>e.level||1));}
function workerLimit(owner){return WORKER_CAP+4*(state.players[owner].capacity||0);}
function researchPrice(key,level){return {gold:key==='fire'?200:key==='stronghold'?250+(level-1)*150:120+level*90,wood:key==='fire'?150:key==='stronghold'?180+(level-1)*100:90+level*70,time:key==='fire'?35:key==='stronghold'?45+level*10:25+level*10};}
function finishResearch(b){const r=b.research;if(r.key==='stronghold'){b.level=r.level;b.max+=500;b.hp+=500;}else state.players[b.owner][r.key]=r.level;b.research=null;}
function cancelProduction(buildingId,jobId){const b=state.entities.find(e=>e.id===buildingId&&e.owner===0&&e.hp>0);if(!b)return false;let task;if(jobId==='research'){task=b.research;if(!task)return false;b.research=null;}else{const index=b.queue.findIndex(q=>String(q.id)===String(jobId));if(index<0)return false;task=b.queue.splice(index,1)[0];}state.players[0].gold+=task.gold||0;state.players[0].wood+=task.wood||0;updateUI();return true;}
