 if(e.type==='altar'||e.type==='roost'){for(const side of [-1,1]){const x=side*(s+8);ctx.fillStyle=horde?'#786745':'#9baea0';ctx.fillRect(x-5,-s*1.3,10,s*1.8);ctx.fillStyle=e.type==='altar'?p.color:horde?'#a26b42':'#739bab';ctx.beginPath();ctx.moveTo(x-9,-s*1.3);ctx.lineTo(x,-s*2);ctx.lineTo(x+9,-s*1.3);ctx.closePath();ctx.fill();}}
 if(horde){ctx.strokeStyle='#806139';ctx.lineWidth=4;for(const side of [-1,1]){const x=side*(s+13);ctx.beginPath();ctx.moveTo(x,s*.5);ctx.lineTo(x,-s*.5);ctx.stroke();ctx.fillStyle='#e0d1a4';ctx.beginPath();ctx.moveTo(x-4,-s*.5);ctx.lineTo(x,-s*.9);ctx.lineTo(x+4,-s*.5);ctx.closePath();ctx.fill();}}
