function repairTick(worker,dt){const b=worker.order.target;if(worker.type!=='worker'||b.owner!==worker.owner||b.type!=='base'||b.hp<=0||b.construction||b.hp>=b.max){finishTask(worker);return;}
 if(Math.hypot(worker.x-b.x,worker.y-b.y)>b.size+28){move(worker,b.x,b.y,dt);return;}
 worker.facing=Math.atan2(b.y-worker.y,b.x-worker.x);if(!worker.action)worker.action={kind:'repair',duration:.8,until:state.time+.8};
 if(!worker.action.emitted&&state.time>=worker.action.until-.4){burst(worker.x,worker.y,'dust',worker.owner);worker.action.emitted=true;}
 b.hp=Math.min(b.max,b.hp+20*dt);if(b.hp===b.max)finishTask(worker);
}
