 const roof=(x,y,w,h)=>{poly([[x-w/2,y],[x,y-h],[x+w/2,y]],'#335d85');poly([[x,y-h],[x+w/2,y],[x+3,y]],'#223b61');ctx.strokeStyle='#9cc5d0';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x-w/2,y);ctx.lineTo(x,y-h);ctx.lineTo(x+w/2,y);ctx.stroke();for(let i=1;i<5;i++){const yy=y-i*h/5,ww=w*(1-i/5);ctx.strokeStyle='#6f95b1';ctx.beginPath();ctx.moveTo(x-ww/2,yy);ctx.lineTo(x+ww/2,yy);ctx.stroke();}};
