 ctx.fillStyle='#09192166';ctx.beginPath();ctx.ellipse(12,25,79,32,0,0,Math.PI*2);ctx.fill();poly([[-64,17],[45,29],[72,4],[-39,-7]],'#7e8c83');poly([[-64,17],[45,29],[45,35],[-64,24]],'#4d6362');
