 masonry(-48,-14,96,37);for(let x=-47;x<48;x+=12){ctx.fillStyle='#c2cbc0';ctx.fillRect(x,-22,7,9);}
 for(const sign of [-1,1]){const x=sign*53;masonry(x-9,-34,18,59);roof(x,-34,29,20);ctx.fillStyle='#183243';ctx.fillRect(x-2,-20,4,12);}
 // Recessed arched gate, portcullis and stone ramp.
