 for(const sign of [-1,1]){ctx.fillStyle='#644c35';ctx.fillRect(sign*20-1,1,2,10);ctx.fillStyle='#ffbd62';ctx.beginPath();ctx.ellipse(sign*20,0,3,5,0,0,Math.PI*2);ctx.fill();}
 ctx.strokeStyle='#d6be85';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-114-level*3);ctx.lineTo(0,-139-level*3);ctx.stroke();poly([[1,-138-level*3],[25,-134-level*3],[21,-121-level*3],[1,-125-level*3]],p.color);
